sal_action_system.md", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "6114cebc-65de-54e3-a37f-28d03e733707", "parent_slug": "store-classification", "slug": "store-master", "name": "Store Master", "item_type": "sub_feature", "description": "", "sort_order": 2201, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "512566e2-a446-5824-a1b0-93bb45b8d96a", "parent_slug": "store-classification", "slug": "store-attribute-sets", "name": "Store Attribute Sets", "item_type": "sub_feature", "description": "", "sort_order": 2202, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "5ba850be-34b0-57d3-9e2f-50246890e7b5", "parent_slug": "tags-and-personas", "slug": "personas", "name": "Personas", "item_type": "sub_feature", "description": "", "sort_order": 2401, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "4815d713-95e9-5c71-946d-eca4b72e088e", "parent_slug": "tags-and-personas", "slug": "tags", "name": "Tags", "item_type": "sub_feature", "description": "", "sort_order": 2402, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "7eafac2c-ca88-5ee1-bd81-f37663cd9576", "parent_slug": "tiers", "slug": "tier-upgrade", "name": "Tier Upgrade", "item_type": "sub_feature", "description": "", "sort_order": 2501, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "515207ac-ccca-596c-bb52-0e6057fb0fae", "parent_slug": "tiers", "slug": "tier-maintenance", "name": "Tier Maintenance", "item_type": "sub_feature", "description": "", "sort_order": 2502, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}, {"id": "9b321b89-2fbe-5fb5-a69b-815fad7cd7a9", "parent_slug": "tiers", "slug": "tier-progress", "name": "Tier Progress", "item_type": "sub_feature", "description": "", "sort_order": 2503, "metadata": {"source_doc_type": "curated_sub_feature", "generation_batch": "feature_knowledge_seed_20260511T091258Z"}, "is_active": true}]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
